  ?s a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Status> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Status/statusid> ?statusid ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Status/status> "Finished" .
