     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/raceid> "19" ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/q2> ?q2 ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/hasDrivers> ?d .
  ?d <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> ?surname .
  FILTER(?q2 != "")
}
ORDER BY ?q2
