SELECT ?name WHERE {
  ?r a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/name> ?name ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?date .
  BIND(SUBSTR(STR(?date),1,7) AS ?ym)
  {
    SELECT (MIN(?ym2) AS ?minym) WHERE {
      ?r2 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?date2 .
      BIND(SUBSTR(STR(?date2),1,7) AS ?ym2)
    }
  }
  FILTER(?ym = ?minym)
}

SELECT ?forename ?surname (SUM(?p) AS ?total)
WHERE {
  ?r a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/driverid> ?did ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/points> ?p .
  ?d a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?did ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> ?surname .
}
GROUP BY ?did ?forename ?surname
ORDER BY DESC(?total)
LIMIT 1

SELECT ?number WHERE {
  ?q a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/raceid> "903"^^<http://www.w3.org/2001/XMLSchema#long> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/q3> ?q3 ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/number> ?number .
  FILTER(CONTAINS(STR(?q3), "1:54"))
}

SELECT (AVG(?ms) AS ?avgLapTime)
WHERE {
  ?d a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> "Lewis" ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> "Hamilton" ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?did .
  ?r a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/name> "Malaysian Grand Prix" ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> 2009 ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?rid .
  ?lt a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime> ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/driverid> ?did ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/raceid> ?rid ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/milliseconds> ?ms .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?ms ?forename ?surname ?racename
WHERE {
  {
    SELECT (MIN(?m) AS ?minms)
    WHERE {
      ?lt a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/milliseconds> ?m .
    }
  }
  ?lt2 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime> ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/milliseconds> ?ms ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/driverid> ?did ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/raceid> ?rid .
  FILTER(xsd:decimal(?ms) = ?minms)

  ?d a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?did ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> ?surname .

  ?r a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?rid ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/name> ?racename .
}

SELECT (((xsd:decimal(?speed853) - xsd:decimal(?speed854)) / xsd:decimal(?speed854)) * 100 AS ?pctFaster)
WHERE {
  ?d a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> "Paul" ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> "di Resta" ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?did .
  ?r1 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result> ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/driverid> ?did ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/raceid> "853"^^xsd:long ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/fastestlapspeed> ?speed853 .
  ?r2 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result> ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/driverid> ?did ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/raceid> "854"^^xsd:long ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/fastestlapspeed> ?speed854 .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
