     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?did ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverref> ?driverref .
