  FILTER(?raceid2 = ?raceid)

  ?last a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result> ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/raceid> ?raceid ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/positionorder> ?lastpo ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/milliseconds> ?lms .
  FILTER(xsd:integer(?lastpo) = ?maxpo)

  BIND(((xsd:decimal(?lms) - xsd:decimal(?wms)) / xsd:decimal(?wms)) * 100 AS ?pct)
}

SELECT ?forename ?surname ?nationality ?racename WHERE {
  {
    SELECT (MAX(?dob) AS ?maxdob) WHERE {
      ?d a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/dob> ?dob .
    }
  }
  ?drv a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/dob> ?maxdob ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> ?surname ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/nationality> ?nationality ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?did .

  {
    SELECT ?did (MIN(?date) AS ?mindate) WHERE {
      ?res a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result> ;
           <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/driverid> ?did ;
           <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/raceid> ?rid .
      ?race a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
            <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?rid ;
            <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?date .
    }
    GROUP BY ?did
  }

  ?res3 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result> ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/driverid> ?did ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/raceid> ?rid3 .
  ?race2 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?rid3 ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?mindate ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/name> ?racename .
}

SELECT ?score ?name ?nationality WHERE {
  ?cr a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/ConstructorResults> ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/ConstructorResults/raceId> ?raceId ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/ConstructorResults/constructorId> ?constructorId ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/ConstructorResults/points> ?points .
  ?r a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?raceId ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/name> ?raceName ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> ?year .
  FILTER(?raceName = "Monaco Grand Prix" && xsd:integer(?year) >= 1980 && xsd:integer(?year) <= 2010)
  ?c a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Constructor> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Constructor/constructorid> ?constructorId ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Constructor/name> ?name ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Constructor/nationality> ?nationality .
}
GROUP BY ?name ?nationality
ORDER BY DESC(SUM(?points))
LIMIT 1

SELECT ?fullname WHERE {
  ?circuit a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Circuit> ;
           <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Circuit/name> "Marina Bay Street Circuit" ;
           <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Circuit/circuitid> ?circuitid .

  ?race a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/circuitid> ?circuitid ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> "2008" ;
